typedef float rational_t;
extern "C" float sqrtf(float);
#define __fsqrt(f) sqrtf(f)

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;
  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
  inline vector3d& operator = ( const vector3d& v )
  { x = v.x; y = v.y; z = v.z; return *this; }
  inline T length2() const
  { return x*x + y*y + z*z; }
};

inline vector3d operator + (const vector3d& a, const vector3d& b)
{ return vector3d(a.x + b.x, a.y + b.y, a.z + b.z); }
inline vector3d operator - (const vector3d& a, const vector3d& b)
{ return vector3d(a.x - b.x, a.y - b.y, a.z - b.z); }
inline vector3d operator * (const vector3d& a, vector3d::T d)
{ return vector3d(d * a.x, d * a.y, d * a.z); }
inline vector3d::T dot(const vector3d& a, const vector3d& b)
{
  vector3d::T t = a.x*b.x + a.y*b.y + a.z*b.z;
  return t;
}

bool collide_segment_sphere( const vector3d& p0, const vector3d& p1,
                             const vector3d& s, rational_t r,
                             vector3d* hit_loc )
{
  // use quadratic formula to see if line segment hits entity sphere
  vector3d v = p1 - p0;
  vector3d w = p0 - s;
  rational_t a = v.length2();
  if ( a < 0.000001f )
  {
    // segment is degenerate (single point)
    if ( w.length2() < r*r )
    {
      *hit_loc = p0;
      return true;
    }
    else
      return false;
  }
  rational_t b = 2.0f * dot( v, w );
  rational_t c = w.length2() - r*r;
  rational_t d = b*b - 4.0f*a*c;
  if ( d > 0.0f )
  {
    b *= -1.0f;
    d = __fsqrt( d );
    rational_t inv_f = 1.0f / (2.0f*a);
    rational_t root1 = (b - d) * inv_f;
    rational_t root2 = (b + d) * inv_f;
    if ( root2 >= 0.0f && root1 <= 1.0f )
    {
      *hit_loc = p0 + v*root1;
      return true;
    }
  }
  return false;
}
